def tri(n):
    result = []
    for i in range(n + 1):
        if i == 0:
            result.append(1)
        elif i == 1:
            result.append(3)
        elif i % 2 == 0:
            # Even index: 2.0, 3.0, 4.0, 5.0, ...
            result.append(1.0 + i / 2)
        else:
            # Odd index: 3, 8, 15, 24, 35, ...
            # i=1: 3, i=3: 8, i=5: 15, i=7: 24, i=9: 35
            # Let k = (i+1)//2: k=1->3, k=2->8, k=3->15, k=4->24, k=5->35
            # 3 = 1*3, 8 = 2*4, 15 = 3*5, 24 = 4*6, 35 = 5*7
            # So k*(k+2)
            k = (i + 1) // 2
            result.append(float(k * (k + 2)))
    return result

