def search(arr):
    """
    Find the element that appears only once in a sorted array.
    """
    if not arr:
        return None

    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        # If mid is odd, adjust to make it even
        if mid % 2 == 1:
            mid -= 1

        # Check if arr[mid] is the unique element
        if mid + 1 < len(arr) and arr[mid] == arr[mid + 1]:
            # The pair starts at mid, so the unique element is to the right
            left = mid + 2
        else:
            # arr[mid] != arr[mid+1], so the unique element is at mid or to the left
            right = mid

    return arr[left]

