def eulerian_num(n, m):
    """
    Find the Eulerian number a(n, m).
    The Eulerian number a(n, m) is the number of permutations of 1, 2, ..., n
    with exactly m ascents.
    """
    # Base cases
    if m < 0 or m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0
    if n == 1:
        return 1 if m == 0 else 0

    # Recurrence: a(n, m) = (m+1)*a(n-1, m) + (n-m)*a(n-1, m-1)
    def helper(n, m):
        if m < 0 or m >= n:
            return 0
        if n == 0:
            return 1 if m == 0 else 0
        if n == 1:
            return 1 if m == 0 else 0
        return (m + 1) * helper(n - 1, m) + (n - m) * helper(n - 1, m - 1)

    return helper(n, m)

