def amicable_numbers_sum(n):
    """
    Sum all amicable numbers from 1 to n.

    Two numbers are amicable if the sum of the proper divisors of each equals the other.
    """
    if n < 2:
        return 0

    # Compute sum of proper divisors for each number up to n
    sum_divisors = [0] * (n + 1)

    for i in range(1, n + 1):
        for j in range(2 * i, n + 1, i):
            sum_divisors[j] += i

    # Find amicable numbers
    total = 0
    for i in range(1, n + 1):
        a = sum_divisors[i]
        if a != i and a <= n and sum_divisors[a] == i:
            # Count each pair only once (i < a)
            if i < a:
                total += i + a

    return total

