def magic_square_test(matrix):
    """
    Determine whether the given matrix is a magic square.

    A magic square is a square matrix where the sum of each row,
    each column, and both main diagonals are all equal.
    """
    n = len(matrix)

    # Check if it's a square matrix
    if n == 0:
        return False
    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the target sum from the first row
    target = sum(matrix[0])

    # Check all rows
    for i in range(n):
        if sum(matrix[i]) != target:
            return False

    # Check all columns
    for j in range(n):
        col_sum = sum(matrix[i][j] for i in range(n))
        if col_sum != target:
            return False

    # Check main diagonal
    diag1_sum = sum(matrix[i][i] for i in range(n))
    if diag1_sum != target:
        return False

    # Check anti-diagonal
    diag2_sum = sum(matrix[i][n - 1 - i] for i in range(n))
    if diag2_sum != target:
        return False

    return True

def next_power_of_2(n):
