def pancake_sort(arr):
    """
    Sort a list of elements using pancake sort.
    """
    def flip(arr, k):
        """Flip the first k+1 elements of the array."""
        arr[:k+1] = reversed(arr[:k+1])

    n = len(arr)
    for curr_size in range(n, 1, -1):
        # Find the index of the maximum element in arr[0..curr_size-1]
        max_idx = 0
        for i in range(1, curr_size):
            if arr[i] > arr[max_idx]:
                max_idx = i

        # If the maximum element is not already at the end
        if max_idx != curr_size - 1:
            # Bring the maximum element to the front
            if max_idx != 0:
                flip(arr, max_idx)
            # Move the maximum element to its correct position
            flip(arr, curr_size - 1)

    return arr

def pancake_sort(arr):
    """
    Sort a list of elements using pancake sort algorithm.
    """
    n = len(arr)
    for current_size in range(n, 1, -1):
        # Find the index of the maximum element in arr[0..current_size-1]
        max_index = 0
        for i in range(1, current_size):
            if arr[i] > arr[max_index]:
                max_index = i

        # If the maximum element is not already at the end of the current subarray
        if max_index != current_size - 1:
            # If the maximum element is not at the beginning, flip it to the beginning
            if max_index != 0:
                arr[:max_index + 1] = reversed(arr[:max_index + 1])
            # Flip the maximum element to its correct position at the end
            arr[:current_size] = reversed(arr[:current_size])

    return arr

