def combinations_colors(lst, n):
    """
    Generate all combinations (with repetition) of the elements of the list,
    where each combination is a tuple of length n, and the elements are in
    non-decreasing order (i.e., combinations with repetition, not permutations).

    Returns a list of tuples.
    """
    if n == 0:
        return [()]
    if n == 1:
        return [(item,) for item in lst]

    result = []
    for i in range(len(lst)):
        for combo in combinations_colors(lst[i:], n - 1):
            result.append((lst[i],) + combo)
    return result

