def is_majority(arr, n, element):
    """
    Check if element is the majority element in a sorted array.
    The majority element occurs more than n/2 times.
    """
    # Find the first occurrence of element using binary search
    # and the last occurrence, then check if count > n/2

    def binary_search_first(arr, n, element):
        low, high = 0, n - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == element:
                result = mid
                high = mid - 1
            elif arr[mid] < element:
                low = mid + 1
            else:
                high = mid - 1
        return result

    def binary_search_last(arr, n, element):
        low, high = 0, n - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == element:
                result = mid
                low = mid + 1
            elif arr[mid] < element:
                low = mid + 1
            else:
                high = mid - 1
        return result

    first = binary_search_first(arr, n, element)
    if first == -1:
        return False

    last = binary_search_last(arr, n, element)
    count = last - first + 1

    return count > n / 2

