def find_lucas(n):
    """
    Find the n'th Lucas number.
    Lucas numbers: L(0) = 2, L(1) = 1, L(n) = L(n-1) + L(n-2)
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 2
