def get_Inv_Count(arr):
    """
    Count inversions in an array using merge sort.
    An inversion is a pair (i, j) such that i < j and arr[i] > arr[j].
    """
    def merge_count(arr, left, right):
        if left >= right:
            return 0

        mid = (left + right) // 2
        inv = merge_count(arr, left, mid) + merge_count(arr, mid + 1, right)

        # Merge step
        temp = []
        i, j = left, mid + 1

        while i <= mid and j <= right:
            if arr[i] <= arr[j]:
                temp.append(arr[i])
                i += 1
            else:
                temp.append(arr[j])
                inv += mid - i + 1
                j += 1

        while i <= mid:
            temp.append(arr[i])
            i += 1

        while j <= right:
            temp.append(arr[j])
            j += 1

        for k in range(left, right + 1):
            arr[k] = temp[k - left]

        return inv

    # Make a copy to avoid modifying the original array
    arr_copy = arr[:]
    return merge_count(arr_copy, 0, len(arr_copy) - 1)

