def max_Product(arr):
    """
    Find a pair with the highest product from a given array of integers.

    Returns a tuple of the two numbers that give the highest product,
    in the order they appear in the original array.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements")

    # Sort to find candidate pairs
    sorted_arr = sorted(arr)

    # Candidate 1: two largest numbers
    prod1 = sorted_arr[-1] * sorted_arr[-2]

    # Candidate 2: two smallest (most negative) numbers
    prod2 = sorted_arr[0] * sorted_arr[1]

    if prod1 >= prod2:
        a, b = sorted_arr[-2], sorted_arr[-1]
    else:
        a, b = sorted_arr[0], sorted_arr[1]

    # Find indices in original array to preserve order
    # We need to find the first occurrence of each value
    idx_a = arr.index(a)
    idx_b = arr.index(b)

    # If a and b are the same value, we need the two distinct occurrences
    if a == b:
        idx_a = arr.index(a)
        idx_b = arr.index(a, idx_a + 1)

    if idx_a < idx_b:
        return (a, b)
    else:
        return (b, a)

