def catalan_number(n: int) -> int:
    """
    Returns the nth Catalan number.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0 or n == 1:
        return 1

    # Using the multiplicative formula: C(n) = C(n-1) * (4n - 2) // (n + 1)
    c = 1
    for i in range(2, n + 1):
        c = c * (4 * i - 2) // (i + 1)
    return c

