def find_solution(a, b, n):
    """
    Find integers x and y such that ax + by = n.
    Returns (x, y) as a tuple, or None if no solution exists.
    Returns the solution with the smallest non-negative x.
    """
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, x1, y1 = extended_gcd(b % a, a)
            x = y1 - (b // a) * x1
            y = x1
            return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)

    if n % g != 0:
        return None

    # Particular solution
    x_p = x0 * (n // g)
    y_p = y0 * (n // g)

    # General solution: x = x_p + (b/g)*t, y = y_p - (a/g)*t
    a_div_g = a // g
    b_div_g = b // g

    if b_div_g == 0:
        # x is fixed
        return (x_p, y_p)

    # Find smallest non-negative x: x = x_p + b_div_g * t >= 0
    # If b_div_g > 0: t >= -x_p / b_div_g, smallest t = ceil(-x_p / b_div_g)
    # If b_div_g < 0: t <= -x_p / b_div_g, smallest t = floor(-x_p / b_div_g)

    if b_div_g > 0:
        t = (-x_p + b_div_g - 1) // b_div_g  # ceil(-x_p / b_div_g)
    else:
        t = -x_p // b_div_g  # floor(-x_p / b_div_g) when b_div_g < 0

    x = x_p + b_div_g * t
    y = y_p - a_div_g * t

    return (x, y)

