def cal_sum(n):
    """
    Calculate the sum of Perrin numbers from index 0 to index n (inclusive).

    Perrin sequence: P(0) = 3, P(1) = 0, P(2) = 2
    P(n) = P(n-2) + P(n-3) for n >= 3
    """
    if n < 0:
        return 0

    # Generate Perrin numbers up to index n
    perrin = [0] * (n + 1)
    perrin[0] = 3
    if n >= 1:
        perrin[1] = 0
    if n >= 2:
        perrin[2] = 2
    for i in range(3, n + 1):
        perrin[i] = perrin[i - 2] + perrin[i - 3]

    return sum(perrin)

