def eulerian_num(n, m):
    """
    Find the Eulerian number a(n, m).

    The Eulerian number a(n, m) counts the number of permutations of 1, 2, ..., n
    with exactly m descents.
    """
    if n < 1 or m < 0 or m >= n:
        return 0
    if m == 0 or m == n - 1:
        return 1

    # Build up the Eulerian number table
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[1][0] = 1
    for i in range(2, n + 1):
        for j in range(0, i):
            if j == 0:
                dp[i][j] = 1
            elif j == i - 1:
                dp[i][j] = 1
            else:
                dp[i][j] = (j + 1) * dp[i - 1][j] + (i - j) * dp[i - 1][j - 1]

    return dp[n][m]

