def largest_subset(nums):
    """
    Find the size of the largest subset of a list of numbers so that every pair is divisible.
    """
    if not nums:
        return 0

    # Remove duplicates and sort
    unique_nums = sorted(set(nums))
    n = len(unique_nums)

    if n == 0:
        return 0

    # dp[i] = size of largest divisible subset ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            # Check if nums[i] is divisible by nums[j]
            if unique_nums[i] % unique_nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp) if dp else 0

