    # Use the recurrence: C(0) = 1, C(n) = C(n-1) * 2 * (2*n - 1) / (n + 1)
    if n == 0:
        return 1

    result = 1
    for i in range(1, n + 1):
        result = result * 2 * (2 * i - 1) // (i + 1)

    return result

