def max_product(arr):
    """
    Find the maximum product formed by multiplying numbers of an increasing subsequence of the array.

    An increasing subsequence is a subsequence where each element is strictly greater than the previous one.
    """
    if not arr:
        return 0

    n = len(arr)
    # dp[i] = maximum product of an increasing subsequence ending at index i
    dp = [0] * n

    for i in range(n):
        dp[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                candidate = dp[j] * arr[i]
                if candidate > dp[i]:
                    dp[i] = candidate

    return max(dp)
