    from math import gcd

    g = gcd(a, b)
    if n % g != 0:
        return None

    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        return None

    if a == 0:
        if n % b == 0:
            return (0, n // b)
        return None

    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        return None

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)
    factor = n // g
    x_base = x0 * factor
    y_base = y0 * factor

    # General solution: x = x_base + k*(b/g), y = y_base - k*(a/g)
    step_x = b // g
    step_y = a // g

    # Find k range where x >= 0 and y >= 0
    # x_base + k*step_x >= 0
    # y_base - k*step_y >= 0  =>  k*step_y <= y_base

    import math

    # Compute lower bound on k from x >= 0
    if step_x > 0:
        k_lo_x = math.ceil(-x_base / step_x)
    elif step_x < 0:
        k_lo_x = math.floor(-x_base / step_x)
    else:
        k_lo_x = 0 if x_base >= 0 else float('inf')

    # Compute upper bound on k from y >= 0
    if step_y > 0:
        k_hi_y = math.floor(y_base / step_y)
    elif step_y < 0:
        k_hi_y = math.ceil(y_base / step_y)
    else:
        k_hi_y = 0 if y_base >= 0 else float('-inf')

    k_lo = k_lo_x
    k_hi = k_hi_y

    if k_lo > k_hi:
        return None

    # Minimize x + y = (x_base + y_base) + k*(step_x - step_y)
    diff = step_x - step_y
    if diff > 0:
        k_opt = k_lo
    elif diff < 0:
        k_opt = k_hi
    else:
        k_opt = k_lo

    x = x_base + k_opt * step_x
    y = y_base - k_opt * step_y

